package checks

import (
	"strings"

	"claudinite.com/checksdk"
)

// shared is the read-only mounted canon, never this pack's to police.
const shared = ".claudinite/shared/"

// trim trims what JavaScript's String.prototype.trim does, so a line reads
// as blank, a comment or a table row exactly as the rules were written to.
func trim(s string) string { return strings.TrimFunc(s, checksdk.IsJSSpace) }

// lineAt is the 1-based line that byte offset i of text falls on.
func lineAt(text string, i int) int { return strings.Count(text[:i], "\n") + 1 }

// uncomment blanks every Python `#` comment to the end of its line, keeping
// the newline so line numbers still count. Quote-aware: a `#` inside a
// string literal is not a comment.
func uncomment(text string) string {
	lines := strings.Split(text, "\n")
	for n, line := range lines {
		var quote byte
		for i := 0; i < len(line); i++ {
			c := line[i]
			switch {
			case quote != 0:
				if c == '\\' {
					i++
				} else if c == quote {
					quote = 0
				}
			case c == '"' || c == '\'':
				quote = c
			case c == '#':
				lines[n] = line[:i]
				i = len(line)
			}
		}
	}
	return strings.Join(lines, "\n")
}
package checks

import "testing"

const (
	paperPDFFile = "references/smith-2024-vessels/smith-2024-vessels.pdf"
	paperDigest  = "references/smith-2024-vessels/digest.md"
)

func TestPaperFolderIndexedFiresOnAPDFWithNoDigest(t *testing.T) {
	fs := run(t, paperFolderIndexed, map[string]string{
		paperPDFFile:    "%PDF",
		referencesIndex: "| [x](smith-2024-vessels/digest.md) |",
	}, paperPDFFile, referencesIndex)
	wantCount(t, fs, 1)
	wantMatch(t, fs[0].Sentence, `smith-2024-vessels has no digest\.md`)
}

func TestPaperFolderIndexedFiresOnADigestTheIndexOmits(t *testing.T) {
	fs := run(t, paperFolderIndexed, map[string]string{
		paperPDFFile:    "%PDF",
		paperDigest:     "# digest",
		referencesIndex: "| [other](other-2020-x/digest.md) |",
	}, paperPDFFile, paperDigest, referencesIndex)
	wantCount(t, fs, 1)
	if fs[0].Path != referencesIndex {
		t.Errorf("finding on %s, want %s", fs[0].Path, referencesIndex)
	}
	wantMatch(t, fs[0].Sentence, `smith-2024-vessels is not linked`)
}

func TestPaperFolderIndexedIsQuietOnADigestedIndexedPaperAndOnToolsAndSupplements(t *testing.T) {
	fs := run(t, paperFolderIndexed, map[string]string{
		paperPDFFile:    "%PDF",
		paperDigest:     "# digest",
		referencesIndex: "| [**smith**](smith-2024-vessels/digest.md) |",
		"references/smith-2024-vessels/supplementary/data.pdf": "%PDF",
		"references/_tools/notes.pdf":                         "%PDF",
	}, paperPDFFile, paperDigest, referencesIndex,
		"references/smith-2024-vessels/supplementary/data.pdf", "references/_tools/notes.pdf")
	wantCount(t, fs, 0)
}
{
  "ruleRoutingGuidance": {
    "belongs": "vessel-image quantification — overlay appearance, render outputs, and the calibration that makes a number micrometres",
    "excludes": "the research-project class and the working lifecycle — those are canon packs"
  }
}
