package checks

import (
	"fmt"
	"regexp"
	"strings"

	"claudinite.com/checksdk"
)

// The paper-intake skill fixes two headings every digest opens and closes on:
// the reason the paper matters to this task, and the table of its extracted
// images. A paper folder that ships figures also ships the figures/README.md
// that describes them.
var (
	digestPath   = regexp.MustCompile(`^references/([^/_][^/]*)/digest\.md$`)
	figureImage  = regexp.MustCompile(`^references/([^/_][^/]*)/figures/[^/]+\.png$`)
	whyHeading   = regexp.MustCompile(`(?mi)^#{1,6}\s.*why this matters to \*?our\*? task`)
	imageHeading = regexp.MustCompile(`(?mi)^#{1,6}\s.*extracted images`)
)

func init() {
	checksdk.Register(checksdk.Check{
		ID:     "paper-digest-shape",
		Tags:   []string{"world"},
		OnFail: "block",
		Since:  "2026-11-01",
		Doc:    ".claudinite/local/packs/vascular-coloring/skills/paper-intake/SKILL.md",
		Why:    "a digest is read in place of the PDF: without its \"why this matters to our task\" section the next session cannot tell what the paper changes, and without its extracted-images section or the figures/README.md the figures are unexplained pixels",
		Run:    paperDigestShape,
	})
}

func paperDigestShape(repo checksdk.Repo) []checksdk.Finding {
	tracked := map[string]bool{}
	for _, f := range repo.Tracked() {
		tracked[f] = true
	}
	var out []checksdk.Finding
	figured := map[string]bool{}
	for _, file := range repo.Tracked() {
		if m := figureImage.FindStringSubmatch(file); m != nil {
			figured[m[1]] = true
		}
		if !digestPath.MatchString(file) {
			continue
		}
		text, _ := repo.Read(file)
		for _, want := range []struct {
			re   *regexp.Regexp
			name string
		}{
			{whyHeading, "a \"Why this matters to *our* task\" section"},
			{imageHeading, "an \"Extracted images\" section"},
		} {
			if !want.re.MatchString(text) {
				out = append(out, checksdk.Finding{
					Path:     file,
					Sentence: fmt.Sprintf("digest lacks %s", want.name),
					Fix:      "add the section the paper-intake skill's step 8 lists, so the digest stands alone",
				})
			}
		}
	}
	for slug := range figured {
		readme := "references/" + slug + "/figures/README.md"
		if !tracked[readme] && strings.TrimSpace(slug) != "" {
			out = append(out, checksdk.Finding{
				Path:     readme,
				Sentence: fmt.Sprintf("%s ships figures with no figures/README.md", slug),
				Fix:      "write figures/README.md showing each figure inline with what its panels and scale bars say (paper-intake step 5)",
			})
		}
	}
	return out
}
EOF
